[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash about the dawn patrol, but Ash has already been waiting.",
    "cited_fact_keys": ["attempt:communicate", "attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "ae0ec0eb-c4ec-42dc-88d9-c8a55b3aaedc",
    "text": "\"Dawn patrol passed at first light.\" Ash informs Wren.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation about their dawn patrol plans.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, however, seems preoccupied and waits for something.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Ash finally breaks the silence, addressing Wren.",
    "cited_fact_keys": ["reaction:1"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "fb74bdcb-ed80-4ec0-a2d0-22847825ecad",
    "text": "Tell Wren about the mill.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": ["attempt:communicate"],
