    "cited_fact_keys": ["attempt:wait"],
    "text": "Meanwhile, Ash waits patiently."
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "cited_fact_keys": ["reaction:1"],
    "text": "Ash speaks to Wren about the mill."
  }
]

