]

[
  {
    "kind": "narration",
    "text": "Ash tries to communicate with Wren about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Wren patiently waits for Ash to finish.",
    "cited_fact_keys": ["attempt:wait"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash tries to convey a message to Wren about their dawn patrol plan.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren patiently awaits Ash's attempt to communicate.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"The mill road is clear.\"",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "6993f0d5-5107-41de-8634-2be5ebe08abb"
  }
]

[
  {
    "kind": "narration",
    "text": "Ash attempts to communicate with Wren about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "c1e17a73-a427-44b6-95e1-076a50c55fb4",
    "text": "Ash, I need to tell you about the lamps.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Ash attempts to communicate with Wren about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Meanwhile, Wren waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "narration",
    "text": "Wren speaks to Ash about the lamps.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Where is the mill?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "'Past the bridge, second left.'",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "23a16730-026d-4ed1-be1b-46575f58a7d7"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation, the topic being the mill stores.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash, meanwhile, remains patient, waiting for Wren to continue.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  },
  {
    "kind": "dialogue",
    "text": "\"Grain and oilskins.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "0517d16d-04bf-4a8b-a222-3e04a83b0cd6"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Who keeps the lighthouse at night?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"Old Marlow, if the lamp is still lit.\" Ash responds.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "329d0df9-91b8-4893-8b1c-85815d38d8a0"
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking if the stalls are open yet.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash waits patiently.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "1d718374-eef1-4adf-a7fc-9b3cfe1d8d48",
    "text": "\"Stalls open at second bell.\"",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren tries to engage Ash in conversation about the dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"],
    "speaker_id": null
  },
  {
    "kind": "action",
    "text": "Ash, however, seems preoccupied and doesn't respond immediately.",
    "cited_fact_keys": ["attempt:wait"],
    "speaker_id": null
  }
]

[
  {
    "kind": "narration",
    "text": "Marlow and Wren attempt to communicate with Ash.",
    "cited_fact_keys": ["attempt:communicate", "attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash waits patiently for their message.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "Ash says to Wren, 'Dawn bell means the first stalls are opening.'",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "472aa77b-f9c4-43e0-8c15-8d984ec6f368"
  },
  {
    "kind": "dialogue",
    "text": "Marlow chimes in, 'Aye, and mind the loose stones past the bridge.'",
    "cited_fact_keys": ["reaction:2"],
    "speaker_id": "59c1ee2b-d9c6-4cff-ba3f-3833ef1eedfd"
  }
]

[
  {
    "kind": "narration",
    "speaker_id": null,
    "text": "Wren tries to engage Ash in conversation about their dawn patrol.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "text": "Meanwhile, Marlow keeps a watchful eye on the surroundings.",
    "cited_fact_keys": ["attempt:observe"]
  },
  {
    "kind": "narration",
    "speaker_id": null,
    "text": "Ash patiently awaits, seemingly lost in thought.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "ae77b715-afab-4bcb-9953-a78693892f9a",
    "text": "\"Dawn bell means the market's waking.\"",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, eager to discuss their plans for the day.",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash, however, is preoccupied and waits for Wren to finish.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "397a8531-8422-4822-aa41-63a4f42e3a62",
    "text": "Ash says to Wren: 'Dawn bell means the market is waking early today, so hurry down with coin and basket before the best bread and freshest fish are gone from the stalls.'",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'Is the old bridge safe to cross?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "speaker_id": "3755eb22-2db6-4d8b-bf0e-758c9fff24ab",
    "text": "'No.' Ash replies curtly.",
    "cited_fact_keys": ["reaction:1"]
  }
]

[
  {
    "kind": "narration",
    "text": "Wren attempts to communicate with Ash, asking, 'What news from the mill, Ash?'",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "action",
    "text": "Ash waits for Wren's response.",
    "cited_fact_keys": ["attempt:wait"]
  },
  {
    "kind": "dialogue",
    "text": "\"It's still standing, unless someone's moved it.\" Ash responds to Wren.",
    "cited_fact_keys": ["reaction:1"],
    "speaker_id": "e563640f-c8bc-45c3-a69d-7016b472984f"
  }
]
